import { useState } from 'react'
import { useForm } from 'react-hook-form';
import * as yup from 'yup';
import { yupResolver } from '@hookform/resolvers/yup';
import { authApi } from '../api/auth';
import { useAppDispatch } from '../redux/index';
import { saveToken } from '../redux/index/user';
import { useNavigate } from "react-router-dom";

interface ILoginForm {
    login: string;
    password: string;
}

export default function useLogin() {
    const dispatch = useAppDispatch()

    const navigate = useNavigate()

    const [error, setError] = useState('');
    const [isLoad, setIsLoad] = useState(false);

    const requiredErrorText = 'Это поле обязаетльно для заполнения';

    const loginSchema = yup.object().shape({
        login: yup.string().required(requiredErrorText),
        password: yup.string().required(requiredErrorText),
    });

    const createForm = useForm<ILoginForm>({
        mode: 'onBlur',
        resolver: yupResolver(loginSchema),
    });

    function onSubmit({ login, password }: ILoginForm) {
        setIsLoad(true)
        authApi.login({ login, password })
            .then(async res => {
                if (res.error) {
                    return setError(res.error)
                }
                if (res.token) {
                    await dispatch(saveToken({ token: res.token }))
                    navigate('/stalker_help/', { replace: true })
                }
            })
            .catch(
                error => {
                    console.log(error)
                    setError(error.message)
                })
            .finally(() => {
                setIsLoad(false)
            })

    }
    return { isLoad, error, createForm, onSubmit: createForm.handleSubmit(onSubmit) }
}
