import React from 'react';
import Card from '@mui/material/Card';
import CardHeader from '@mui/material/CardHeader';
import CardContent from '@mui/material/CardContent';
import Avatar from '@mui/material/Avatar';
import Typography from '@mui/material/Typography';
import { red } from '@mui/material/colors';
import { useAppSelector } from '../../redux/index';
import { ITradeItem } from '../../models/trade';
import { IconButton } from '@mui/material';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';

export default function TradeCard({ item, editBegin }: { item: ITradeItem, editBegin: (e: string) => void }) {
    const { id } = useAppSelector(state => state.user);

    function toggleEdit() {
        editBegin(item.id)
    }
    function toggleDelete() {
        // editBegin(item.id)
    }
    return (
        <Card sx={{}}>
            <CardHeader
                avatar={
                    <Avatar src={item.photo_100} sx={{ bgcolor: red[500], ...(id === item.from_id ? { border: '3px solid blue' } : {}) }} aria-label="recipe" />
                }
                action={
                    id === item.from_id ? <>
                        <IconButton aria-label="settings" onClick={toggleEdit}>
                            <EditIcon />
                        </IconButton>
                        <IconButton aria-label="settings" onClick={toggleDelete}>
                            <DeleteIcon />
                        </IconButton>
                    </>
                        : <></>
                }
                title={`${item.first_name} ${item.last_name}`}
            />
            {/* <CardMedia
                component="img"
                height="194"
                image="/static/images/cards/paella.jpg"
                alt="Paella dish"
            /> */}
            <CardContent>
                <Typography variant="body2" sx={{ color: 'text.secondary', whiteSpace: "pre-wrap" }}>
                    {item.message}
                </Typography>
            </CardContent>
        </Card >
    );
}