import React, { useEffect, useState } from 'react'
import { tradesApi } from '../../api/trades'
import { Box, Button, CircularProgress, Drawer, Input, InputLabel, TextField } from '@mui/material'
import TradeCard from '../../components/trade-card'
import { Controller, useForm } from 'react-hook-form';
import * as yup from 'yup';
import { yupResolver } from '@hookform/resolvers/yup';
import { ITradeItem } from '../../models/trade';

const fabStyle = {
    position: 'fixed',
    bottom: 16,
    right: 16,
    zIndex: 99999,
};

export default function MainPage() {
    const [loading, setLoading] = useState(false);
    const [state, setState] = useState<{
        isInit: boolean, totalCount: number, page: number, pageSize: number, list: ITradeItem[]
    }>({ isInit: true, totalCount: 0, page: 1, pageSize: 20, list: [] })
    const [showTradeMenu, setShowTradeMenu] = useState(false);

    const [edit, setEdit] = useState<{
        isEdit: boolean,
        editId: null | string,
        message: string
    }>({
        isEdit: false,
        editId: null,
        message: '',
    });

    useEffect(() => {
        getTrades(1, false)
    }, [])

    function getTrades(page: number, isAppend: boolean) {
        setLoading(true)
        tradesApi.getAll({ page: page, pageSize: state.pageSize })
            .then(res => {
                setState(prev => ({
                    ...prev,
                    page,
                    isInit: true,
                    list: isAppend ? [...prev.list, ...res.data] : res.data,
                    totalCount: res.totalCount
                }))
            })
            .finally(() => setLoading(false))
    }

    function getMoreItems() {
        getTrades(state.page + 1, true)
    }

    function toggleOpenTradeMenu() {
        setShowTradeMenu(true)
    }

    function toggleCloseTradeMenu() {
        setShowTradeMenu(false)
    }

    async function addTrade(model: { message: string }) {
        tradesApi.addTrade({ message: model.message })
            .then(res => {
                console.log({ res })
                if (res) {
                    getTrades(1, false)
                    toggleCloseTradeMenu()
                }
            })
    }
    async function editTrade(model: { message: string }) {
        tradesApi.updateTrade({ tradeId: edit.editId || '', message: model.message })
            .then(res => {
                console.log({ res })
                if (res) {
                    getTrades(1, false)
                    toggleCloseTradeMenu()
                }
            })
    }

    const requiredErrorText = 'Это поле обязаетльно для заполнения';

    const tradeSchema = yup.object().shape({
        message: yup.string().required(requiredErrorText),
    });

    const createForm = useForm<{ message: string }>({
        mode: 'all',
        resolver: yupResolver(tradeSchema),
    });

    function editBegin(id: string) {
        const editItem = state.list.find(item => item.id === id);
        setEdit(prev => ({ ...prev, isEdit: true, editId: id, message: editItem?.message || '' }));
        createForm.setValue('message', editItem?.message || '');
        toggleOpenTradeMenu()
    }

    return (
        <div className="container">
            <h3>Торговая площадка</h3>
            <div>
                <Button onClick={toggleOpenTradeMenu} fullWidth variant='contained'>Добавить объявление</Button>
                {!state.isInit ?
                    <>
                        <CircularProgress />
                    </>
                    : <>
                        <div style={{ display: 'grid', padding: "20px 5px", gap: "15px", gridTemplateColumns: '1fr', width: "100%" }}>
                            {
                                state.list.map((item: any) => (
                                    <TradeCard
                                        editBegin={editBegin}
                                        item={item} />
                                ))
                            }

                        </div>
                        {
                            state.totalCount > state.list.length && <div style={{ display: 'flex', width: "100%", alignItems: 'center', justifyContent: 'center', marginTop: "20px" }}>
                                <Button
                                    disabled={loading}
                                    onClick={getMoreItems} variant='contained'>
                                    {
                                        loading ? <CircularProgress />
                                            : 'Показать еще'
                                    }
                                </Button>
                            </div>
                        }
                    </>
                }
            </div>

            <Drawer sx={(theme) => ({
                ...fabStyle,
            })}
                open={showTradeMenu}
                onClose={toggleCloseTradeMenu} anchor='bottom'>
                <div style={{ padding: '10px' }}>
                    <form onSubmit={createForm.handleSubmit(edit.isEdit ? editTrade : addTrade)}>
                        <Controller
                            control={createForm.control}
                            name={"message"}
                            render={({ field }) =>
                                <TextField
                                    fullWidth
                                    id="outlined-multiline-flexible"
                                    label="Объявление"
                                    multiline
                                    maxRows={4}
                                    sx={{ mb: 2 }}
                                    {...field}
                                    error={!!createForm.formState.errors?.message?.message}
                                />
                            }
                        />
                        <Button
                            type='submit'
                            fullWidth
                            variant='contained'>{edit.isEdit ? 'Сохранить' : 'Добавить'}</Button>
                    </form>
                </div>
            </Drawer>
        </div>
    )
}
