import React from 'react'
import { Accordion, AccordionSummary, Typography, AccordionDetails } from '@mui/material'
import ArrowDownwardIcon from '@mui/icons-material/ArrowDownward';
import ArrowDropDownIcon from '@mui/icons-material/ArrowDropDown';
import { faqConstant } from '../../constants/faq';

export default function FaqPage() {
    if (faqConstant.length <= 0) {
        return <div className="container">
            В процессе наполнения
        </div>
    }
    return (
        <div className="container">
            {
                faqConstant.map(faqItem => (
                    <Accordion key={faqItem.id}>
                        <AccordionSummary
                            expandIcon={<ArrowDropDownIcon />}
                            aria-controls="panel2-content"
                            id="panel2-header"
                        >
                            <Typography><div dangerouslySetInnerHTML={{ __html: faqItem.title }} /></Typography>
                        </AccordionSummary>
                        <AccordionDetails>
                            <Typography>
                                <div dangerouslySetInnerHTML={{ __html: faqItem.content }} />
                            </Typography>
                        </AccordionDetails>
                    </Accordion>
                ))
            }
            {


            }
        </div>
    )
}
