
export function setCookie(
    key: string,
    value: string,
    expireDays: null | number = 7,
    expireHours?: number | null,
    expireMinutes?: number | null,
    expireSeconds?: number | null,
) {
    let expireDate = new Date();
    if (expireDays) {
        expireDate.setDate(expireDate.getDate() + expireDays);
    }
    if (expireHours) {
        expireDate.setHours(expireDate.getHours() + expireHours);
    }
    if (expireMinutes) {
        expireDate.setMinutes(expireDate.getMinutes() + expireMinutes);
    }
    if (expireSeconds) {
        expireDate.setSeconds(expireDate.getSeconds() + expireSeconds);
    }
    document.cookie =
        key +
        '=' +
        escape(value) +
        ';domain=' +
        window.location.hostname +
        ';path=/' +
        ';expires=' +
        expireDate.toUTCString();
}

export function deleteCookie(name: string) {
    setCookie(name, '', null, null, null, 1);
}

export function getCookieValue(name: string) {
    const matches = document.cookie.match(
        new RegExp(`(?:^|; )${name.replace(/([.$?*|{}()[]\/+^])/g, '\\$1')}=([^;]*)`),
    );
    return matches ? decodeURIComponent(matches[1]) : undefined;
}


export class AuthCookieStorage {
    static key = 'aucr';

    static default = {
        token: null,
    };

    static get auth() {
        const auth = getCookieValue(AuthCookieStorage.key);
        if (!auth) {
            return AuthCookieStorage.default;
        }
        return JSON.parse(auth);
    }

    static set auth(val) {
        setCookie(AuthCookieStorage.key, JSON.stringify(val), 1);
    }

    static reset() {
        deleteCookie(AuthCookieStorage.key);
    }
}
