
import { instance } from ".";

export const tradesApi = {
    getAll(body: { page?: number, pageSize?: number }) {
        return instance.post('/trades/all', body)
            .then(res => res.data)
    },
    addTrade(body: { message: string }) {
        return instance.post('/trades/add', body)
            .then(res => res.data)
    },
    deleteTrade(body: { tradeId: string }) {
        return instance.post('/trades/delete', body)
            .then(res => res.data)
    },
    updateTrade(body: { tradeId: string, message: string }) {
        return instance.post('/trades/update', body)
            .then(res => res.data)
    },
};